\]"}}, "difficulty": "knowledge", "steps_analysis": {"step_1": {"physical_theorem": "Newton's Law of Universal Gravitation and Gravitational Force equals to Weight", "result_quantity": [{"name": "Mass of the Earth", "equation": "M = \frac{g R^{2}}{G}", "symbol": "M", "value": "\frac{g R^{2}}{G}", "unit": "kg"}]}, "step_2": {"physical_theorem": "Newton's Law of Universal Gravitation and Newton's Second Law (Centripetal Force)", "result_quantity": [{"name": "Centripetal acceleration of the satellite", "equation": "a=\frac{R^{2}g}{\left(R+h\right)^{2}}", "symbol": "a", "value": "\frac{R^{2}g}{\left(R+h\right)^{2}}", "unit": "m/s²"}]}, "step_3": {"physical_theorem": "Newton's Law of Universal Gravitation and Centripetal Force Formula", "result_quantity": [{"name": "Orbital speed of the satellite", "equation": "v = R \sqrt{\frac{g}{R+h}}", "symbol": "v", "value": "R \sqrt{\frac{g}{R+h}}", "unit": "m/s"}]}}}
